"use strict";(self.webpackChunkplantmind_industrial_intelligence_knowledge_hub=self.webpackChunkplantmind_industrial_intelligence_knowledge_hub||[]).push([[6253],{7766:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"knowledge":[{"type":"link","label":"Knowledge Taxonomy","href":"/knowledge-hub/knowledge/","docId":"knowledge-index","unlisted":false},{"type":"category","label":"01 Start Here","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Industrial AI in Plain English","href":"/knowledge-hub/knowledge/01-start-here/industrial-ai-plain-english","docId":"start-here/PMKB-SH-001","unlisted":false}],"href":"/knowledge-hub/knowledge/category/01-start-here"},{"type":"category","label":"02 Executive Center","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"CEO Guide to Industrial AI","href":"/knowledge-hub/knowledge/02-executive-center/ceo-guide","docId":"executive-center/PMKB-EXE-001","unlisted":false}],"href":"/knowledge-hub/knowledge/category/02-executive-center"},{"type":"category","label":"03 Industrial AI Foundations","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Predictive Maintenance Explained","href":"/knowledge-hub/knowledge/03-industrial-ai-foundations/predictive-maintenance","docId":"industrial-ai-foundations/PMKB-AIF-001","unlisted":false},{"type":"link","label":"Industrial Knowledge Graphs","href":"/knowledge-hub/knowledge/03-industrial-ai-foundations/industrial-knowledge-graphs","docId":"industrial-ai-foundations/PMKB-KG-001","unlisted":false}],"href":"/knowledge-hub/knowledge/category/03-industrial-ai-foundations"},{"type":"category","label":"04 Industrial Systems","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Industrial Systems","href":"/knowledge-hub/knowledge/industrial-systems/","docId":"industrial-systems/industrial-systems-index","unlisted":false}],"href":"/knowledge-hub/knowledge/category/04-industrial-systems"},{"type":"category","label":"05 Industry Playbooks","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Industrial AI Playbook for Power Generation","href":"/knowledge-hub/knowledge/05-industry-playbooks/power-generation","docId":"industry-playbooks/PMKB-PWR-001","unlisted":false},{"type":"link","label":"Industrial AI Playbook for Cement","href":"/knowledge-hub/knowledge/05-industry-playbooks/cement","docId":"industry-playbooks/PMKB-CEM-001","unlisted":false}],"href":"/knowledge-hub/knowledge/category/05-industry-playbooks"},{"type":"category","label":"06 Industrial Solution Packs","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"FGD and Air Pollution Control Intelligence","href":"/knowledge-hub/knowledge/06-solution-packs/fgd-air-pollution-control","docId":"solution-packs/PMKB-FGD-001","unlisted":false}],"href":"/knowledge-hub/knowledge/category/06-industrial-solution-packs"},{"type":"category","label":"07 PlantMind in Action","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"PlantMind in Action","href":"/knowledge-hub/knowledge/plantmind-in-action/","docId":"plantmind-in-action/plantmind-in-action-index","unlisted":false}],"href":"/knowledge-hub/knowledge/category/07-plantmind-in-action"},{"type":"category","label":"08 Real Data & AI Lab","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"NASA C-MAPSS Dataset Card and RUL Learning Guide","href":"/knowledge-hub/knowledge/08-data-ai-lab/nasa-cmapss","docId":"data-ai-lab/PMKB-DATA-001","unlisted":false}],"href":"/knowledge-hub/knowledge/category/08-real-data--ai-lab"},{"type":"category","label":"09 Connectivity & Integration","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"PlantMind Connect \u2014 No Rip-and-Replace Architecture","href":"/knowledge-hub/knowledge/09-connectivity-integration/plantmind-connect","docId":"connectivity-integration/PMKB-CON-001","unlisted":false},{"type":"link","label":"Connecting PlantMind to SAP \u2014 Architecture Overview","href":"/knowledge-hub/knowledge/09-connectivity-integration/sap-architecture","docId":"connectivity-integration/PMKB-SAP-001","unlisted":false}],"href":"/knowledge-hub/knowledge/category/09-connectivity--integration"},{"type":"category","label":"10 PlantMind OS","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"PlantMind OS","href":"/knowledge-hub/knowledge/plantmind-os/","docId":"plantmind-os/plantmind-os-index","unlisted":false}],"href":"/knowledge-hub/knowledge/category/10-plantmind-os"},{"type":"category","label":"11 Governance & Trust","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Governance & Trust","href":"/knowledge-hub/knowledge/11-governance-trust","docId":"governance-trust/governance-trust-index","unlisted":false}],"href":"/knowledge-hub/knowledge/category/11-governance--trust"},{"type":"category","label":"12 Industrial AI Case Library","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Industrial AI Case Library","href":"/knowledge-hub/knowledge/case-library/","docId":"case-library/case-library-index","unlisted":false}],"href":"/knowledge-hub/knowledge/category/12-industrial-ai-case-library"},{"type":"category","label":"13 Research & Market Intelligence","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Research & Market Intelligence","href":"/knowledge-hub/knowledge/research-intelligence/","docId":"research-intelligence/research-intelligence-index","unlisted":false}],"href":"/knowledge-hub/knowledge/category/13-research--market-intelligence"},{"type":"category","label":"14 Glossary & Reference","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Glossary & Reference","href":"/knowledge-hub/knowledge/glossary-reference/","docId":"glossary-reference/glossary-reference-index","unlisted":false}],"href":"/knowledge-hub/knowledge/category/14-glossary--reference"}]},"docs":{"case-library/case-library-index":{"id":"case-library/case-library-index","title":"Industrial AI Case Library","description":"Cases become publishable only when company, use case and outcome trace to a credible source. Vendor-reported outcomes remain clearly attributed claims rather than independently verified facts.","sidebar":"knowledge"},"connectivity-integration/PMKB-CON-001":{"id":"connectivity-integration/PMKB-CON-001","title":"PlantMind Connect \u2014 No Rip-and-Replace Architecture","description":"Keep the systems you already have. Add intelligence on top. PlantMind Connect is positioned as an integration layer that reads selected data, preserves source ownership, contextualizes it and supports governed workflows. Any connector or write-back capability must be verified per product version and site.","sidebar":"knowledge"},"connectivity-integration/PMKB-SAP-001":{"id":"connectivity-integration/PMKB-SAP-001","title":"Connecting PlantMind to SAP \u2014 Architecture Overview","description":"Treat SAP as the enterprise system of record for the relevant asset and work objects. PlantMind can map analytical context to those objects and propose a governed workflow. Start read-only; define any notification or order creation as a separately approved write path.","sidebar":"knowledge"},"data-ai-lab/PMKB-DATA-001":{"id":"data-ai-lab/PMKB-DATA-001","title":"NASA C-MAPSS Dataset Card and RUL Learning Guide","description":"C-MAPSS is a learning benchmark for degradation and RUL methods, not evidence that a model will predict failures in a cement mill, power-plant fan or customer asset. Preserve NASA provenance, label transformations and simulations, and recheck current availability before use.","sidebar":"knowledge"},"executive-center/PMKB-EXE-001":{"id":"executive-center/PMKB-EXE-001","title":"CEO Guide to Industrial AI","description":"Begin with a costly, frequent and decisionable operating problem\u2014not an enterprise-wide AI program. Require a named process owner, usable data, an intervention path, a baseline and a clear statement of what the pilot will not automate.","sidebar":"knowledge"},"glossary-reference/glossary-reference-index":{"id":"glossary-reference/glossary-reference-index","title":"Glossary & Reference","description":"The governed reference layer for industrial terminology, acronyms, standards, KPI definitions, asset classes and failure taxonomies. Definitions will preserve sector context rather than flatten it into generic language.","sidebar":"knowledge"},"governance-trust/governance-trust-index":{"id":"governance-trust/governance-trust-index","title":"Governance & Trust","description":"Industrial AI earns operational trust through visible evidence, bounded authority, human approval, secure integration and reviewable decisions.","sidebar":"knowledge"},"industrial-ai-foundations/PMKB-AIF-001":{"id":"industrial-ai-foundations/PMKB-AIF-001","title":"Predictive Maintenance Explained","description":"Predictive maintenance is not \u201cpredict every failure.\u201d It is the disciplined use of condition, process and history to create actionable warning before a maintenance decision deadline. Failure-mode definition and workflow design matter as much as algorithm choice.","sidebar":"knowledge"},"industrial-ai-foundations/PMKB-KG-001":{"id":"industrial-ai-foundations/PMKB-KG-001","title":"Industrial Knowledge Graphs","description":"An industrial knowledge graph makes relationships queryable: which tag measures which asset, which asset performs which process function, which work order followed which event, and which document supports which decision. Its value is governed context and lineage\u2014not graph technology for its own sake.","sidebar":"knowledge"},"industrial-systems/industrial-systems-index":{"id":"industrial-systems/industrial-systems-index","title":"Industrial Systems","description":"Reference architecture for PLC, DCS, SCADA, historians, MES, ERP, CMMS/EAM, QMS, OPC UA, MQTT and edge/cloud boundaries. Content will distinguish control, records, context and intelligence responsibilities.","sidebar":"knowledge"},"industry-playbooks/PMKB-CEM-001":{"id":"industry-playbooks/PMKB-CEM-001","title":"Industrial AI Playbook for Cement","description":"Cement intelligence must follow material and heat through the plant. Raw-mix chemistry, grinding performance, preheater/calciner behavior, kiln stability, cooler efficiency, fuel and draft interact; an isolated model can mistake process change for equipment failure.","sidebar":"knowledge"},"industry-playbooks/PMKB-PWR-001":{"id":"industry-playbooks/PMKB-PWR-001","title":"Industrial AI Playbook for Power Generation","description":"Power-generation intelligence must respect the steam-water cycle, combustion and heat transfer, rotating-train behavior, condenser conditions, auxiliaries and emissions controls. A useful first pilot isolates one decision and one operating envelope rather than promising fleet-wide optimization.","sidebar":"knowledge"},"knowledge-index":{"id":"knowledge-index","title":"Knowledge Taxonomy","description":"Browse fourteen governed domains\u2014from executive education and industrial AI foundations to sector playbooks, integration, evidence and reference knowledge.","sidebar":"knowledge"},"plantmind-in-action/plantmind-in-action-index":{"id":"plantmind-in-action/plantmind-in-action-index","title":"PlantMind in Action","description":"Sector implementation journeys and bounded pilot blueprints. No customer journey or outcome will be published without verified evidence and approval.","sidebar":"knowledge"},"plantmind-os/plantmind-os-index":{"id":"plantmind-os/plantmind-os-index","title":"PlantMind OS","description":"Knowledge for Connect, Context Engine, Industrial Knowledge Graph, Digital Twin, Copilot, Agents, Flow, Business Value Engine and Data Lab. Capability status must be verified as Demo, Planned, Custom or Implemented.","sidebar":"knowledge"},"research-intelligence/research-intelligence-index":{"id":"research-intelligence/research-intelligence-index","title":"Research & Market Intelligence","description":"Industrial AI trends, standards, regulation, M&A, funding, product moves and CEO interpretation. Fast-changing objects require source date, last-checked date and an expiry/review policy.","sidebar":"knowledge"},"solution-packs/PMKB-FGD-001":{"id":"solution-packs/PMKB-FGD-001","title":"FGD and Air Pollution Control Intelligence","description":"FGD intelligence is a coupled process-and-reliability problem. SO\u2082 removal, reagent preparation, absorber chemistry, slurry circulation, oxidation air and gypsum dewatering interact. Models must never substitute for calibrated emissions monitoring, environmental procedures or operator authority.","sidebar":"knowledge"},"start-here/PMKB-SH-001":{"id":"start-here/PMKB-SH-001","title":"Industrial AI in Plain English","description":"Industrial AI is a decision-support layer above the systems that already run the plant. It combines operating signals with asset, process and work context to identify patterns worth investigating. It does not replace control systems, engineering judgment or accountable decision-makers.","sidebar":"knowledge"}}}}')}}]);